<template><div :class="embeddedStore?'s1-ui':'s1-ui ivu-card ivu-card-bordered'"><div :style="embeddedStore?'':'padding:20px'"><header class="ui-header"><div><h2>经营资格</h2><p>基础经营、模拟交易与真实渠道分别判定，结论读取当前事实。</p></div></header><DatasetSwitch :available="demoAvailable&&!embeddedStore" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data"/><div class="ui-search"><label v-if="!embeddedStore">商户<BusinessSelect v-model="targetStore" type="stores" placeholder="按店铺或主体名称选择" @input="clear"/></label><label>类目（可选）<CategorySelect v-model="categoryId" purpose="eligibility" :store-id="targetStore" @input="clear"/></label><div class="ui-actions"><Button type="primary" :disabled="!targetStore" @click="reload">按当前事实计算</Button><Button @click="reset">重置</Button></div></div><p v-if="!targetStore" class="ui-empty">请选择商户后查看资格。</p><template v-if="selected"><p class="ui-note">判定时间：{{date(selected.evaluatedAt)}} · 下一条件边界：{{date(selected.validUntil)}}<br/>来源：{{status(selected.environment)}}／{{status(selected.authorizedMode)}}</p><Row :gutter="16"><Col v-for="tier in tiers" :key="tier.key" :span="8"><section class="ui-section"><h3>{{tier.title}}</h3><Tag :color="selected[tier.flag]===true?'green':'orange'">{{selected[tier.flag]===true?'条件满足':selected[tier.flag]===false?'条件未满足':'结论未知'}}</Tag><ul style="padding-left:18px;line-height:2"><li v-for="(r,index) in selected.reasons[tier.key]||[]" :key="index">{{reason(r.code)}} <button v-if="destination(r)" class="ui-link" @click="navigate(r)">{{destination(r).title}}</button><span v-else class="ui-meta">请联系相应平台人员</span></li></ul></section></Col></Row><DetailSection v-for="cat in selected.categories||[]" :key="cat.categoryId" :title="'类目：'+(cat.categoryName||cat.categoryId)" :grid="false"><div v-for="tier in tiers" :key="tier.key"><strong>{{tier.title}}</strong> <Tag :color="cat[tier.flag]===true?'green':'orange'">{{cat[tier.flag]===true?'满足':'待补条件'}}</Tag><p v-for="(r,i) in cat.reasons&&cat.reasons[tier.key]||[]" :key="i">{{reason(r.code)}}</p></div></DetailSection><DetailSection title="来源与版本追溯" :grid="false"><Table :columns="sourceColumns" :data="sources" no-data-text="未提供来源摘要"/><p class="ui-meta">来源指纹 {{selected.sourceFingerprint}}</p></DetailSection></template></div></div></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import BusinessSelect from './components/BusinessSelect';import CategorySelect from './components/CategorySelect';import DetailSection from './components/DetailSection';export default {mixins:[page],components:{PageStatus,BusinessSelect,CategorySelect,DetailSection},props:{embeddedStore:String},data:()=>({targetStore:'',categoryId:'',tiers:[{key:'BASIC',flag:'BASIC_ELIGIBLE',title:'基础经营条件'},{key:'MOCK',flag:'MOCK_READY',title:'模拟交易前置条件'},{key:'REAL',flag:'REAL_READY',title:'真实渠道前置条件'}],sourceColumns:[{title:'来源',key:'name',minWidth:180},{title:'对象／版本',key:'reference',minWidth:220},{title:'当前状态／核验时间',key:'summary',minWidth:220}]}),computed:{sources(){const value=this.selected&&this.selected.sourceVersions||{},rows=[];for(const [key,item] of Object.entries(value)){if(key==='qualifications'&&Array.isArray(item)){item.forEach(q=>rows.push({name:'资质',reference:String(q.id||q.type||'未提供')+' · v'+(q.version==null?'未提供':q.version),summary:this.date(q.validTo||q.approvedAt)}));continue;}if(key.startsWith('qualificationPolicy:')){rows.push({name:'类目资质策略',reference:key.split(':').slice(1).join(' · '),summary:'v'+item});continue;}const names={store:'店铺',agreement:'合作协议',agreementEvidenceAvailable:'协议附件可用',rule:'佣金规则',MOCKChannel:'模拟渠道',REALChannel:'真实渠道',MOCKReceiver:'模拟接收关系',REALReceiver:'真实接收关系'};const name=key.startsWith('category:')?'类目':names[key];if(!name)continue;if(item&&typeof item==='object')rows.push({name,reference:String(item.name||item.id||key.split(':')[1]||'未提供')+' · v'+(item.version==null?'未提供':item.version)+(item.revision!=null?' / 提交v'+item.revision:''),summary:[item.state?this.status(item.state):null,item.lastSyncState?this.status(item.lastSyncState):null,item.verifiedAt?this.date(item.verifiedAt):null,item.enabled===false?'停用':null].filter(Boolean).join(' · ')||'已读取来源事实'});else rows.push({name,reference:typeof item==='boolean'?(item?'是':'否'):String(item),summary:''});}return rows;}},watch:{embeddedStore(value){this.targetStore=value||'';this.clear();if(value)this.reload();},'$route.query.targetStore'(value){if(!this.embeddedStore){this.targetStore=value||'';this.clear();if(value)this.reload();}}},mounted(){this.targetStore=this.embeddedStore||this.$route.query.targetStore||(this.demoActive?this.demoStore:'');if(this.targetStore)this.reload();},methods:{clear(){this.ticket++;this.selected=null;this.error='';this.loading=false;},reset(){this.categoryId='';if(!this.embeddedStore)this.targetStore='';this.clear();if(this.embeddedStore)this.reload();},reload(){if(!this.targetStore)return;return this.latest(()=>this.read('/stores/'+this.targetStore+'/eligibility',{categoryId:this.categoryId||undefined}),v=>{this.selected=v;},()=>{this.selected=null;});},destination(r){const map={STORE_INACTIVE:['store.read','/s1/stores/'+this.targetStore,'核查商户'],LICENSE_EXPIRED:['store.read','/s1/stores/'+this.targetStore,'核查资质'],CATEGORY_NOT_ALLOWED:['catalog.configure','/s1/categories','核查类目'],QUALIFICATION_POLICY_PENDING:['catalog.configure','/s1/categories','核查类目策略'],CHANNEL_PENDING:['channel.onboard','/s1/submerchants','核查渠道'],SUB_MERCHANT_UNVERIFIED:['channel.onboard','/s1/submerchants','核查二级商户'],CHANNEL_LIMIT_UNVERIFIED:['channel.onboard','/s1/submerchants','核查渠道能力'],RECEIVER_UNVERIFIED:['channel.receiver','/s1/receivers','核查接收关系']};const v=r.code.startsWith('AGREEMENT_')?['agreement.read','/s1/agreements','核查协议']:r.code.startsWith('RULE_')?['rule.read','/s1/commission-rules','核查规则']:map[r.code];return v&&this.can(v[0])?{path:v[1],title:v[2]}:null;},navigate(r){const d=this.destination(r);if(d)this.link(d.path,{targetStore:this.targetStore});}}};</script>
